	Y[45] = ATRMT4Core(S4, S4, S4, 20, &atr_o_tr);	// AT20 s40
	Y[44] = atr_o_tr;
	Y[47] = ATRMT4Core(S5, S5, S5, 20, &atr_o_tr);	// AT20 s100
	Y[46] = atr_o_tr;
	Y[49] = ATRMT4Core(S6, S6, S6, 20, &atr_o_tr);	// AT20 ramp
	Y[48] = atr_o_tr;
	Y[51] = ATRMT4Core(S7, S7, S7, 20, &atr_o_tr);	// AT20 rampdn
